    @pytest.fixture(autouse=True, scope="function")
    def setup_browser(self, request):
        cls = request.cls

        current_test = request.node.name
        is_incognito_case = bool(re.search(r"onlineUsr|maxUsrAccess", current_test))
        
        # 取得本次 Pytest 總共要執行的 Case 數量（用來判斷是不是只單跑一個 Case）
        total_cases_to_run = request.session.testscollected
        is_single_case_run = (total_cases_to_run == 1)

        # 如果前一個 Case 是無痕，或者是其他原因導致 driver 沒清乾淨，先重置
        if is_incognito_case and cls.driver is not None:
            print("偵測到已有瀏覽器，因下一個是特定無痕 Case，先重置關閉...")
            cls.driver.quit()
            cls.driver = None

        # 只有當瀏覽器還沒啟動時，才執行啟動與登入
        if cls.driver is None:
            print(f"\n正在啟動瀏覽器並登入 EMS... (目標 Case: {current_test})")
            match cls.browser:
                case "chrome":
                    options = webdriver.ChromeOptions()
                    options.add_argument('ignore-certificate-errors')
                    if is_incognito_case: 
                        print("啟用 Chrome 無痕模式")
                        options.add_argument('--incognito')
                    prefs = {
                        "download.default_directory": cls.downloadpath,
                        "download.prompt_for_download": False,
                        "download.directory_upgrade": True
                    }
                    options.add_experimental_option("prefs", prefs)
                    cls.driver = webdriver.Chrome(options)
                    
                case "edge":
                    options = webdriver.EdgeOptions()
                    options.add_argument('ignore-certificate-errors')
                    if is_incognito_case: 
                        print("啟用 Edge 無痕模式")
                        options.add_argument('--inprivate')
                    prefs = {
                        "download.default_directory": cls.downloadpath,
                        "download.prompt_for_download": False,
                        "download.directory_upgrade": True
                    }
                    options.add_experimental_option("prefs", prefs)
                    cls.driver = webdriver.Edge(options) 
                    
                case "firefox":
                    options = webdriver.FirefoxOptions()
                    options.add_argument('-ignore-certificate-errors')
                    if is_incognito_case:
                        print("啟用 Firefox 無痕模式")
                        options.set_preference("browser.privatebrowsing.autostart", True)
                    options.set_preference("browser.download.folderList", 2)
                    options.set_preference("browser.download.dir", cls.downloadpath)
                    cls.driver = webdriver.Firefox(options) 

            cls.driver.implicitly_wait(cls.waitTime)
            cls.driver.maximize_window()
            cls.driver.get(cls.emsURL)
            loginEMS(cls, cls.emsUsr, cls.emsPwd)
            time.sleep(3)
        else:
            print(f"\n共用既有瀏覽器執行下一案: {current_test}")

        yield  # 執行測試案件主體

        # 核心判斷：測試結束後的關閉時機
        # 情況 A：如果是特定無痕 Case，跑完立刻關閉，免得污染後面
        # 情況 B：如果使用者在 RUN.py 只單獨點名跑「這一個 Case」，跑完立刻關閉
        if is_incognito_case or is_single_case_run:
            if is_incognito_case:
                print(f"\n特定無痕 Case [{current_test}] 執行完畢，關閉瀏覽器。")
            elif is_single_case_run:
                print(f"\n單一 Case [{current_test}] 獨立執行完畢，關閉瀏覽器。")
                
            if cls.driver:
                cls.driver.quit()
                cls.driver = None

