        self.driver.find_element(By.LINK_TEXT, "Maintenance").click()
        time.sleep(3)
        self.driver.find_element(By.LINK_TEXT, "Schedule").click()
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_create_collector > a").click()
        time.sleep(3)
        Select(self.driver.find_element(By.ID, "schedule_type")).select_by_visible_text("Firmware upgrade")
        time.sleep(3)
        for cardType in range(len(fwUploadName)):
            if dutAllCardID[cardType] == "0":
                continue
            self.driver.find_element(By.ID, "add_row").click()
            elementScrolledIntoView(self, self.driver.find_element(By.ID, "devtype"))
            Select(self.driver.find_element(By.ID, "devtype")).select_by_visible_text(dutType)
            Select(self.driver.find_element(By.ID, "uploadTo")).select_by_visible_text(fwUploadName[cardType])
