        self.driver.find_element(By.ID, "timeout").click()
        self.driver.find_element(By.ID, "timeout").send_keys(Keys.CONTROL + "a")
        self.driver.find_element(By.ID, "timeout").send_keys(Keys.DELETE)
        self.driver.find_element(By.ID, "timeout").send_keys("180")
        self.driver.find_element(By.ID, "schedule_name").click()
        self.driver.find_element(By.ID, "schedule_name").clear()
        self.driver.find_element(By.ID, "schedule_name").send_keys("AutoTest_FirmwareUpgrade")
        self.driver.find_element(By.CSS_SELECTOR, ".button_center").click()
        time.sleep(5)
        entryPosition = getPositionByCol(self, "schedule_table", "ScheduleTime", scheduleTime + timeZone)
        waitScheduleSuccess (self, entryPosition)
        time.sleep(180)
        #Maintanence table summary assert
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleStatus").text == "Finish"
