        self.driver.find_element(By.ID, "add_row").click()
        self.driver.find_element(By.XPATH, "//label[contains(.,\'" + dutNodeName + "\')]").location_once_scrolled_into_view
        self.driver.find_element(By.XPATH, "//label[contains(.,\'" + dutNodeName + "\')]").click()
        self.driver.find_element(By.XPATH, "//input[@value=\'Search ONT\']").click()
        for index in range(ontCount):
            time.sleep(3)
            clickBySlotPortOnt(self, dutName, ontSlotIDList[index], ontPortIDList[index], ontOntIDList[index])
        self.driver.find_element(By.CSS_SELECTOR, "#add_table .button").click()
        self.driver.find_element(By.CSS_SELECTOR, ".button_center").click()
        time.sleep(3)
        entryPosition = getPositionByCol(self, "schedule_table", "ScheduleTime", scheduleTime + timeZone)
        waitScheduleSuccess (self, entryPosition)
        getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").click()
        time.sleep(2)
        self.driver.find_element(By.CSS_SELECTOR, "#AddDevMagement .modal-content").screenshot("./report/OntResetDetail.png")
        self.driver.find_element(By.CSS_SELECTOR, "#AddDevMagement span").click()
        #Maintanence table summary assert
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleStatus").text == "Finish"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Name").text == "AutoTest_ONTReset"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Type").text == "ONT Load Default"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleType").text == "Once"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").text == "Success"
        #Maintanence table detail 1 assert
        getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").click()
        time.sleep(3)
        with assume: assert getScheduleResultByCol (self, "Index") == "1"
        with assume: assert getScheduleResultByCol (self, "Schedule Name") == "AutoTest_ONTReset"
        minTime = datetime.strptime(scheduleTime, dateFormat)
        maxTime = minTime + timedelta(seconds = 600)
        timeResult = getScheduleResultByCol (self, "Execute Time").removesuffix(timeZone) 
        with assume: assert minTime <= datetime.strptime(timeResult, dateFormat) <= maxTime
        resultSummary = getScheduleResultByCol (self, "Result Summary")
        resultSummaryList = resultSummary.split(",")
        resultSummaryList = [re.sub(r"^.*:", "", i,flags = re.DOTALL) for i in resultSummaryList]
        with assume: assert int(resultSummaryList[0]) >= 0
        with assume: assert int(resultSummaryList[1]) == 0
        #Maintanence table detail 2 assert
        detailScheduleNameList = getScheduleResultDetailListByCol (self, "ScheduleName")
        detailExecuteDateList = getScheduleResultDetailListByCol (self, "Date")
        detailDeviceNameList = getScheduleResultDetailListByCol (self, "DeviceName")
        detailSlotList = getScheduleResultDetailListByCol (self, "SlotID")
        detailPortList = getScheduleResultDetailListByCol (self, "PortID")
        detailONTList = getScheduleResultDetailListByCol (self, "OntID")
        detailResultList = getScheduleResultDetailListByCol (self, "Result ")
        detailCauseList = getScheduleResultDetailListByCol (self, "Cause ")
        with assume: assert checkAllElementInListAre (detailScheduleNameList, "AutoTest_ONTReset")
        with assume: assert checkAllElementInListPartialMatch (detailExecuteDateList, scheduleTime)
        with assume: assert checkAllElementInListAre (detailDeviceNameList, dutName)
        if "OLT" not in dutType:
            with assume: assert detailSlotList == ontSlotIDList
        with assume: assert detailPortList == ontPortIDList
        with assume: assert detailONTList == ontOntIDList
        with assume: assert checkAllElementInListAre (detailResultList, "Success")
        with assume: assert checkAllElementInListPartialMatch (detailCauseList, "Success")
        self.driver.find_element(By.CSS_SELECTOR, "#AddDevMagement span").click()
        time.sleep(300)
        #Check the ont just reboot 
        for index in range(ontCount):
            time.sleep(3)
            with assume: assert await checkOntUptime(dutIp, dutAdminName, dutAdminPwd, ontFlagList[index], [ontSlotIDList[index], ontPortIDList[index], ontOntIDList[index]]) <= 1200

